      tl: { form: () => date('tl', 'due', 'Final report due', iso(addW(today, 70))) + num('tl', 'inc', 'Inception (working days)', 10) + num('tl', 'tools', 'Tools, ethics and approvals', 10) + num('tl', 'field', 'Fieldwork', 15) + num('tl', 'ana', 'Analysis', 10) + num('tl', 'draft', 'Drafting the report', 8) + num('tl', 'rev', 'Client review per round', 10) + sel('tl', 'rounds', 'Review rounds before final', [[1, 'One'], [2, 'Two']], 1),
        calc: () => { const g = (k, d) => +get('tl', k, d); let end = new Date(get('tl', 'due', iso(addW(today, 70)))); if (isNaN(end)) end = addW(today, 70); const rounds = g('rounds', 1);
          const steps = [['Inception report signed', g('inc', 10)], ['Tools and ethics approved', g('tools', 10)], ['Fieldwork complete', g('field', 15)], ['Analysis and emerging findings', g('ana', 10)], ['Draft report submitted', g('draft', 8)]];
          for (let r = 1; r <= rounds; r++) steps.push([r === rounds ? 'Final report submitted (after review and revision)' : `Revised draft after review ${r}`, g('rev', 10) + 3]);
          let t = end; const rows = []; for (let i = steps.length - 1; i >= 0; i--) { const s = addW(t, -steps[i][1]); rows.unshift([steps[i][0], s, t, steps[i][1]]); t = s; }
          const start = rows[0][1]; const late = start < today; const total = steps.reduce((a, s) => a + s[1], 0);
          return `<div class="kbs">${big(nice(start), 'latest start date')}${big(total, 'working days in total')}</div>${late ? `<p class="kw">The start date is already in the past. Ask for a later deadline, fewer review rounds, or a smaller scope.</p>` : ''}<ol class="ktl">${rows.map(([n, s, e, d]) => `<li><b>${esc(n)}</b><span>${nice(s)} to ${nice(e)} · ${d} working days</span></li>`).join('')}</ol><p class="kn">Weekends are skipped; public holidays are not. Each review round includes 3 days for you to revise.</p>`; } },
      ql: { form: () => num('ql', 'grp', 'Groups or locations to cover', 4, { hint: 'For example 4 districts, or 2 districts × 2 group types', min: 1 }) + num('ql', 'fgd', 'Focus groups per group', 2, { hint: 'Two to three per group usually reaches saturation' }) + num('ql', 'kii', 'Key informant interviews in total', 16) + num('ql', 'fl', 'Minutes per focus group', 90) + num('ql', 'kl', 'Minutes per interview', 45) + num('ql', 'tx', 'Transcription hours per audio hour', 5, { hint: '4 to 6 by hand; less with AI transcription plus checking', step: 0.5 }) + num('ql', 'an', 'Coding and analysis hours per audio hour', 3, { step: 0.5 }),
        calc: () => { const g = (k, d) => +get('ql', k, d); const fg = g('grp', 4) * g('fgd', 2); const audio = (fg * g('fl', 90) + g('kii', 16) * g('kl', 45)) / 60; const tx = audio * g('tx', 5), an = audio * g('an', 3);
          return `<div class="kbs">${big(fg, 'focus groups')}${big(g('kii', 16), 'interviews')}${big(fmt(audio, 1), 'hours of audio')}</div><table class="kt3"><tr><td>Transcription and translation</td><td>${fmt(tx)} hours (${fmt(tx / 7, 1)} days)</td></tr><tr><td>Coding and analysis</td><td>${fmt(an)} hours (${fmt(an / 7, 1)} days)</td></tr><tr><td>Facilitator days in the field (about 2 groups or 4 interviews a day)</td><td>${fmt(Math.ceil(fg / 2 + g('kii', 16) / 4))} days</td></tr></table><p class="kn">Plan a facilitator and a note-taker for every group. Check saturation as you go: if new interviews add nothing new, you may stop early.</p>`; } },
      inv: { form: () => num('inv', 'fee', 'Professional fee for this milestone (₹)', 300000, { step: 1000 }) + num('inv', 'exp', 'Reimbursable expenses (₹)', 0, { step: 500, hint: 'Only if the contract allows' }) + sel('inv', 'gst', 'Registered for GST?', [['y', 'Yes'], ['n', 'No']], 'y') + num('inv', 'gr', 'GST rate (%)', 18, { step: 1 }) + num('inv', 'tds', 'TDS the client deducts (%)', 10, { hint: 'Often 10% on professional fees; confirm the current rate and threshold', step: 1 }),
        calc: () => { const g = (k, d) => +get('inv', k, d); const fee = g('fee', 300000), ex = g('exp', 0); const gst = get('inv', 'gst', 'y') === 'y' ? (fee + ex) * g('gr', 18) / 100 : 0; const inv = fee + ex + gst; const tds = fee * g('tds', 10) / 100; const net = inv - tds;
          return `<div class="kbs">${big(rs(inv), 'invoice total')}${big(rs(net), 'reaches your bank')}</div><table class="kt3"><tr><td>Professional fee</td><td>${rs(fee)}</td></tr>${ex ? `<tr><td>Reimbursable expenses</td><td>${rs(ex)}</td></tr>` : ''}<tr><td>GST</td><td>${rs(gst)}</td></tr><tr><td><b>Invoice total</b></td><td><b>${rs(inv)}</b></td></tr><tr><td>Less TDS deducted by the client</td><td>− ${rs(tds)}</td></tr><tr><td><b>Paid to you</b></td><td><b>${rs(net)}</b></td></tr></table><p class="kn">The GST you collect is paid to the government, and the TDS is credited against your income tax (check Form 26AS). Set aside both before you spend. Clients abroad may be treated differently. Not tax advice: check with a tax adviser.</p>`; } },
